TESTDATA["pet6-t3"] = {"title": "Cambridge PET 6 · Test 3", "format": "2010", "reading": [{"part": 1, "items": [{"n": 1, "text": "", "img": "data:image/jpeg;base64,", "q": "Tony wants Elsa to", "options": ["ask her boss for a week’s holiday starting tomorrow.", "find out if she can have time off next month.", "go away with him next week for a month."], "answer": "B"}, {"n": 2, "text": "", "img": "data:image/jpeg;base64,", "q": "", "options": ["Ring and tell us if you are satisfied with the service we have delivered.", "Telephone us if arrangements for collecting goods are not satisfactory.", "Call us to take the goods back if you are not satisfied with them."], "answer": "C"}, {"n": 3, "text": "", "img": "data:image/jpeg;base64,", "q": "", "options": ["Ruth has kept to her plan despite the change in the weather.", "Ruth may not visit the coast if the bad weather continues.", "Ruth intends to leave the mountains early to visit the coast."], "answer": "B"}, {"n": 4, "text": "", "img": "data:image/jpeg;base64,", "q": "", "options": ["Remove this food from the container before placing in a microwave oven.", "It is advisable to use a suitable container for cooking this food.", "You should avoid putting this food in a microwave oven."], "answer": "C"}, {"n": 5, "text": "", "img": "data:image/jpeg;base64,", "q": "", "options": ["You will have to pay more to borrow DVDs after 1st January.", "Please return all borrowed DVDs before 1st January.", "There will be additional DVDs to borrow from 1st January."], "answer": "A"}]}, {"part": 2, "people": [{"n": 6, "name": "Jessica", "text": "Jessica is arranging her boss’s retirement party. She is looking for somewhere in the town centre that can provide a traditional evening meal for around 100 guests.", "answer": "F"}, {"n": 7, "name": "Amelia", "text": "Amelia is organising her 18th birthday party for 80 friends. She loves to dance and sing along to her favourite tunes. She wants to offer drinks and snacks rather than a sit-down meal.", "answer": "A"}, {"n": 8, "name": "James and Amanda", "text": "James and Amanda need somewhere to hold their wedding party. They want to be able to take photos outdoors. Most of their 100 guests are coming by car and some will need overnight accommodation.", "answer": "G"}, {"n": 9, "name": "Jens", "text": "Jens wants to thank his staff of six by taking them out for a day in the countryside. He wants somewhere where they can do lots of fun activities and have a meal.", "answer": "D"}, {"n": 10, "name": "Sophie", "text": "Sophie is organising her company’s annual two-day conference. Several meeting rooms are required, one of which must be able to hold 200 people. They will all need to stay one night.", "answer": "B"}], "texts": [{"letter": "A", "title": "Rumbola", "text": "Rumbola is available for private bookings of up to 100 people. Hire one of our DJs, who will keep you and your guests moving to the music all night. If you know the words, he’ll encourage you to join in! We have no restaurant, but light refreshments are available."}, {"letter": "B", "title": "The Darlington Centre", "text": "This modern building, situated in the countryside, is perfect for all business events. We have rooms of varying sizes – the Haversham is the largest with space for 300 people. Included in the price are meals, overnight accommodation and tea/coffee."}, {"letter": "C", "title": "Amazon Café", "text": "Situated in the town centre, this restaurant is an exciting place to celebrate a birthday or other special event. The restaurant is decorated to look and sound like a rainforest. Busy and fun, it is popular with young people who like Brazilian food and listening to loud music."}, {"letter": "D", "title": "Sunbury Park", "text": "This country house has space for 200 people at events such as weddings and formal dinners. In our beautiful park, we offer a variety of exciting sports and team-building games. As overnight accommodation is not provided, your event will be free from the interruptions often found in a hotel. We have a large car park."}, {"letter": "E", "title": "Narborough Manor", "text": "In the historic town centre, this beautiful hotel is the perfect setting for a wedding or birthday party. We can organise entertainment such as magic shows or live music. Lovely paintings and fireplaces make the perfect background for photos. Our dining room seats up to 80."}, {"letter": "F", "title": "Hudsons", "text": "This beautiful building dates from 1750 and is the last of its kind in this central location – all around it are shops and businesses. During the day it serves light lunches but in the evening it turns into an old-fashioned, formal restaurant, which can be hired for parties of up to 200 people."}, {"letter": "G", "title": "Hillcourt House", "text": "This family-run hotel is famous for its beautiful gardens. It can host private or small business events. The dining room holds 150 and meeting rooms hold 10–20. The hotel is in the countryside but close to two motorways and has plenty of parking spaces."}, {"letter": "H", "title": "Tiger Tom", "text": "At weekends, this stylish town-centre restaurant is full of famous faces, but on certain weekdays it can be hired for birthday parties or business events. The menus are modern and it is possible to play your own choice of music while you have your meal."}]}, {"part": 3, "title": "The Albuquerque Balloon Festival", "text": "Every autumn, the sky above the desert city of Albuquerque in the south-western United States turns into a mass of bright colours. This is the Albuquerque Balloon Festival, an annual nine-day event.\n\nThe first festival was held in 1972 to celebrate the 50th birthday of the local radio station. There were about a dozen hot-air balloons and they took off from the car park in the middle of Albuquerque. From these small beginnings, the festival has grown steadily. This year at least a thousand balloons from over one third of the countries of the world are expected at its current out-of-town site.\n\nWhat to see\n\nThe pilots are in radio contact with each other and all light up the burners of their balloons at the same time. These are known as ‘balloon glows’ and are an opportunity to take fantastic photographs. However, you must arrive just after night has fallen or before 5.30 am to see these ‘glows’ as the balloons rise into the dark sky.\n\nDuring the day, you can walk around among the balloons and chat to the pilots as they prepare for take-off. The balloons come in all sizes and colours, some in the shapes of animals or cartoon characters – and, of course, well-known products such as varieties of soft drinks and fast food. Kids will love it.\n\nIn the afternoon, why not take to the sky yourself by arranging a balloon flight over the desert with one of the many companies offering balloon rides? Another possibility is to take the cable car from the desert floor to the top of the nearby mountains, the longest such ride anywhere, and enjoy a bird’s-eye view of the festival. There are plenty of other attractions for visitors of all ages, including balloon races and firework displays on the opening evening and the last three evenings of the festival.\n\nThe Albuquerque Box\n\nThis is a local wind pattern that creates perfect conditions for balloonists. The Sandia Mountains protect the balloons from strong winds, and at the same time create gentler currents of wind at different heights. This means that by rising or descending, skilful pilots can control the direction of their balloons.\n\nPractical advice\n\nBuy your tickets in advance (they are available online) and save yourself a long wait to get into the festival site. Wear several layers of thin clothing. At night and in the early morning it can be quite cool, but during the day sunglasses and suncream are essential. Bring a flashlight for night-time events and, of course, bring your camera. If you’re not a digital photographer, you’ll need high-speed film for evening and night-time pictures.", "items": [{"n": 11, "q": "The Albuquerque Balloon Festival lasts over a week.", "answer": "A"}, {"n": 12, "q": "The first festival took place at the opening of the local radio station.", "answer": "B"}, {"n": 13, "q": "The pilots use hand signals to communicate with each other.", "answer": "B"}, {"n": 14, "q": "The “balloon glow” happens before sunrise and after sunset.", "answer": "A"}, {"n": 15, "q": "Members of the public are forbidden to enter the balloon take-off area.", "answer": "B"}, {"n": 16, "q": "Some advertising balloons join in the festival.", "answer": "A"}, {"n": 17, "q": "You can take a balloon ride to the top of the nearby mountains.", "answer": "B"}, {"n": 18, "q": "You can watch a firework show every evening of the festival.", "answer": "B"}, {"n": 19, "q": "The geography of the area around Albuquerque makes it particularly suitable for ballooning.", "answer": "A"}, {"n": 20, "q": "Visitors should be prepared for a range of temperatures.", "answer": "A"}]}, {"part": 4, "title": "", "text": "Kal Kaur Rai has always been interested in fashion and has just won the title of Young Achiever of the Year at the Asian Business Awards. Ever since she was a child, she has drawn clothes and designed patterns. She never told her hard-working parents, who own a supermarket, that she wanted to turn her hobby into a career. She thought they expected her to go into a more established business, so she went to university to do a management degree.\n\nAfter university, she moved to London and worked in an advertising agency. one naa to attend industry events but couldn’t afford the designer clothes she liked. She started making skirts and tops for herself. When her friends saw her clothes, they asked her to make things for them. She then found a small shop in London willing to take her designs on a sale-or- return basis. They were very popular and nothing came back. This encouraged her to leave her advertising job, take out a £20,000 loan and begin her own womenswear label. Kal’s parents were not angry about her career change and said they would support her, which really pleased her. Her clothes are now on sale in over 70 stores and her business has an income of over £500,000. Her clothes appear in fashion magazines, she designs for pop stars and she has just gained public recognition by winning this award. Her business has come a long way and she knows she is extremely lucky. ‘What I do is my hobby — and I get paid for it! But remember, I’ve worked hard for this.’", "items": [{"n": 21, "q": "What is the writer trying to do in the text?", "options": ["encourage fashion designers to make better business plans", "compare a job in fashion with other choices of career", "give details of recent changes in the fashion industry", "explain how a woman set up a fashion business"], "answer": "D"}, {"n": 22, "q": "What does the reader learn about Kal’s parents?", "options": ["They wanted Kal to help them run the family business.", "They did not realise that Kal wanted to work in fashion.", "They insisted Kal should continue with her job in advertising.", "They did not think Kal worked hard enough at university."], "answer": "B"}, {"n": 23, "q": "Kal decided to borrow £20,000 when", "options": ["all her clothes in the London shop were sold.", "her friends asked her to make clothes for them.", "she lost her job at the advertising agency.", "the fashion industry was in a period of growth."], "answer": "A"}, {"n": 24, "q": "What does Kal say about her career?", "options": ["She plans to open more stores.", "She believes that she deserves her success.", "She particularly enjoys designing for famous people.", "She expects more people to buy her clothes after the award."], "answer": "B"}, {"n": 25, "q": "What might Kal say now about her career?", "options": ["My management degree has helped me more than anything else. It’s so important that young people interested in fashion can deal with money.", "I’ve learnt so much working for other fashion designers. Without this experience, I couldn’t have started my own business.", "Running a fashion business is a dream come true and my parents being happy with my choice makes it even more special.", "Even when I was at university, my friends liked the clothes I made. This encouraged me to think about a career in fashion."], "answer": "C"}]}, {"part": 5, "title": "Sweden’s Ice Hotel", "text": "The village of Jukkasjärvi is (0) ……… (in) Swedish Lapland, and winter temperatures there can reach −40°C. But 6,000 holidaymakers [26] go there annually, to visit what is probably Europe’s most unusual accommodation. In this hotel you eat, drink, and sleep in rooms made [27] ice. If you want, you can [28] get married in one. The bar is ice too, and putting hot drinks on it is obviously not [29]! The bedrooms are around −4°C, but fortunately guests are [30] with special sleeping bags that will keep [31] warm in the coldest of temperatures. [32] outdoor clothes can be supplied too, if needed. The hotel is never more than six months old [33] it melts in summer, and [34] winter it is rebuilt. Creating the hotel [35] 10,000 tonnes of ice, plus 30,000 tonnes of snow.", "gaps": {"26": {"options": ["therefore", "ever", "also", "still"], "answer": "D"}, "27": {"options": ["by", "of", "within", "for"], "answer": "B"}, "28": {"options": ["even", "however", "already", "yet"], "answer": "A"}, "29": {"options": ["supported", "recognised", "recommended", "agreed"], "answer": "C"}, "30": {"options": ["given", "offered", "provided", "delivered"], "answer": "C"}, "31": {"options": ["these", "those", "they", "them"], "answer": "D"}, "32": {"options": ["Suitable", "Convenient", "Acceptable", "Satisfactory"], "answer": "A"}, "33": {"options": ["although", "because", "so", "while"], "answer": "B"}, "34": {"options": ["other", "any", "each", "another"], "answer": "C"}, "35": {"options": ["brings", "puts", "fetches", "takes"], "answer": "D"}}}], "writing": [{"part": 1, "title": "Here are some sentences about a well-known painting, La Gioconda (or Mona Lisa).", "items": [{"n": 1, "first": "Probably, no other painting is as famous as La Gioconda.", "before": "La Gioconda is probably", "after": "painting in the world.", "answers": ["the most famous", "the best known", "the best-known"]}, {"n": 2, "first": "Nobody is sure of the identity of the woman in the painting.", "before": "Nobody is sure", "after": "the woman in the painting is.", "answers": ["who", "about who"]}, {"n": 3, "first": "People find the smile of the woman in the painting interesting.", "before": "People are", "after": "in the smile of the woman in the painting.", "answers": ["interested"]}, {"n": 4, "first": "It took Leonardo a long time to paint this picture.", "before": "Leonardo spent a long time", "after": "this picture.", "answers": ["painting", "finishing", "doing", "working on", "on"]}, {"n": 5, "first": "Does anyone know what this picture is worth today?", "before": "Does anyone know how", "after": "this picture is worth today?", "answers": ["much", "much money", "many pounds", "many dollars", "many euros"]}]}, {"part": 2, "items": [{"n": 6, "kind": "message", "task": "You arranged to meet your English friend Sally next Tuesday, but you have to change the time.\n\nWrite an email to Sally. In your email, you should\n• suggest a new time to meet on Tuesday\n• explain why you need to change the time\n• remind Sally where you arranged to meet.\n\nWrite 35–45 words on your answer sheet.", "points": ["proporre un nuovo orario per vedersi martedì", "spiegare perché deve cambiare orario", "ricordare a Sally dove si incontrano"]}]}, {"part": 3, "items": [{"n": 7, "kind": "letter", "task": "Your Scottish penfriend has written to you for advice.\n\nNext month, I’m moving with my family to a different area. I have to choose between going to a small school in the countryside or a large school in the centre of town. What should I do?\n\nNow write a letter to your penfriend, giving your advice.\nWrite your letter in about 100 words on your answer sheet."}, {"n": 8, "kind": "story", "task": "Your English teacher has asked you to write a story.\nYour story must begin with this sentence:\n\nAs the man left the café, Maria saw that his phone was still on the table.\n\nWrite your story in about 100 words on your answer sheet."}]}], "listening": [{"part": 1, "audio": "audio/pet6-t3-l1.mp3", "items": [{"n": 1, "q": "What regular exercise does David do at the moment?", "img": "data:image/jpeg;base64,", "options": ["", "", ""], "answer": "B"}, {"n": 2, "q": "What should Suzie take to Emma’s house?", "img": "data:image/jpeg;base64,", "options": ["", "", ""], "answer": "C"}, {"n": 3, "q": "Which kind of T-shirt did the boy choose?", "img": "data:image/jpeg;base64,", "options": ["", "", ""], "answer": "C"}, {"n": 4, "q": "What frightened the man?", "img": "data:image/jpeg;base64,", "options": ["", "", ""], "answer": "A"}, {"n": 5, "q": "Where is the man calling from?", "img": "data:image/jpeg;base64,", "options": ["", "", ""], "answer": "C"}, {"n": 6, "q": "How did the woman spend her last holiday?", "img": "data:image/jpeg;base64,", "options": ["", "", ""], "answer": "B"}, {"n": 7, "q": "Where is the girl’s purse?", "img": "data:image/jpeg;base64,", "options": ["", "", ""], "answer": "C"}]}, {"part": 2, "intro": "You will hear a radio interview with a ballet dancer called Elena Karpov, who is talking about her life and career.", "audio": "audio/pet6-t3-l2.mp3", "items": [{"n": 8, "q": "Elena decided to become a dancer when she was", "options": ["seven.", "nine.", "eleven."], "answer": "B"}, {"n": 9, "q": "At ballet school in New York, Elena", "options": ["was the only student from Bulgaria.", "found learning the language hard.", "learned to be independent."], "answer": "C"}, {"n": 10, "q": "What does Elena say about the ballet called Cinderella?", "options": ["Children will enjoy it.", "The music was unfamiliar to her.", "She saw it when she was a child."], "answer": "A"}, {"n": 11, "q": "In her free time, Elena likes to", "options": ["go sightseeing.", "go to clubs.", "go shopping."], "answer": "C"}, {"n": 12, "q": "What does Elena often do for her fans?", "options": ["She gives them a flower.", "She signs one of her photographs.", "She sends them a free ticket."], "answer": "A"}, {"n": 13, "q": "What does Elena like best about her job?", "options": ["appearing on television", "doing something she loves", "travelling to different countries"], "answer": "B"}]}, {"part": 3, "intro": "You will hear a group leader talking to some students who are going to visit an important athletics event in Birmingham.", "audio": "audio/pet6-t3-l3.mp3", "notes": "Athletics Championships\n\nDate of college trip: [14] 15th\nNumber of sportspeople who will compete: [15]\nHow the group will travel to Birmingham: by [16]\nWhat group members should take on the day: [17]\nName of the website page: [18]\nWhich day other details will be available to students: [19]", "answers": {"14": ["March", "Mar", "of March"], "15": ["520"], "16": ["train", "trains", "by train", "by the train", "the train", "rail", "railway", "railroad", "by rail"], "17": ["identity card", "identity cards", "ID card", "ID cards", "an identity card", "an identity cards", "an ID card", "an ID cards", "your identity card", "your identity cards", "your ID card", "your ID cards", "their identity card", "their identity cards", "their ID card", "their ID cards", "card", "cards"], "18": ["BIRINFO", "BIR INFO"], "19": ["Friday", "Fri", "on Friday", "this Friday"]}}, {"part": 4, "intro": "You will hear a conversation between a boy, Rolf, and a girl, Maria, talking about the jobs they would like to do in the future.", "audio": "audio/pet6-t3-l4.mp3", "items": [{"n": 20, "q": "Maria would like to travel a lot as part of her job.", "answer": "A"}, {"n": 21, "q": "Maria is confident she will be able to work for an airline.", "answer": "B"}, {"n": 22, "q": "Rolf intends to do a job connected with his degree.", "answer": "B"}, {"n": 23, "q": "Maria and Rolf agree it is important to have a good salary.", "answer": "A"}, {"n": 24, "q": "Maria hopes to work for several different employers.", "answer": "B"}, {"n": 25, "q": "Rolf’s ambition is to manage his own company one day.", "answer": "B"}]}]};
